# coding: utf-8
"""Source-image checked ethics, institutions and accident cases; preserve initial answers."""
import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')}
initial={r['question_id']:r for r in json.loads((ROOT/'config/authored_batches/S7_016_independent_answers.json').read_text())}
items=[]
def add(q,stem,values,reasons,answer,solution,core,theories,concept,conditions,discipline='apt_5',ambiguity='',citations=(),law=False,verdicts=None,figure=False):
 r=by[q];assert len(values)==len(reasons)==5
 if verdicts is None:verdicts=['選択対象' if i==answer else '選択対象ではない' for i in range(1,6)]
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions,choices={str(i):dict(value=v,verdict=j,reason=w) for i,(v,j,w) in enumerate(zip(values,verdicts,reasons),1)},figures='原典の設問・全5肢・否定・時点を実画像確認。'+('組合せ候補表の全セルを照合。' if figure else '設問固有図なし。'),ambiguity=ambiguity,evidence=initial[q]['source_images_viewed'],core_concept=core,required_knowledge=core+'。'+solution,solution=solution,independent_answer=initial[q]['independent_answer'],independent_solution_note='原典画像から構成した初回判断はS7_016_independent_answers.jsonに公式正答参照前に保存。'+initial[q]['reason']+'。後続の一次資料確認と初回判断を区別する。',answer_reason=solution,learning_points='対象、条件、時点を先に確認する。'+core+'を具体的な事例へ適用し、技術的原因・法的要件・倫理的判断のどれを問うか区別する。',theory_references=theories,discipline_id=discipline,concept_id=concept,classification_reason='原典の全肢確認による主題は'+core+'。'+('初期の技術者倫理から、設問の中心である'+discipline+'へ分類修正。' if r['discipline_id']!=discipline else '既存分野の主題を内容で確認。'),calculation='false',figure=str(figure).lower(),law=str(law).lower(),evaluation=dict(knowledge_novelty='2' if law or concept=='accident_learning' else '1',reasoning_steps='2',calculation_load='0',figure_reading='1' if figure else '0',difficulty='3' if ambiguity else '2',difficulty_reason='物理専攻者には制度・社会的責任の対象や事故の時系列が新規知識。各記述を判断した後に、数・表・最も不適切という指定へ対応させる。'+('判決と不起訴、一次資料の不足も独立に検討する。' if ambiguity else '')),citations=list(citations),foundationality='high',transferability='high',source_reference_date=r['year']))
def e(*x):return ['theory:ethics:'+s for s in x]
def c(*x):return ['theory:compliance:'+s for s in x]
add('H24-REG-APT-13','特定非営利活動法人の公益目的、収益・報酬、競争、会社員の参加を4記述で判定する。',['ア○・イ○・ウ○・エ×','ア×・イ○・ウ○・エ×','ア○・イ○・ウ×・エ×','ア○・イ○・ウ×・エ○','ア○・イ×・ウ×・エ×'],['ウを適切とするのが誤り。活動分野の法定と営利企業の競争保護のための制限は別である。','アを誤り、ウを正しいとした点が逆。2012年4月以降は20分野である。','公益目的と報酬の区別に基づくア・イの肯定、ウ・エの否定が一致する。','エを適切とするのが誤り。営利企業の社員であること自体は参加を禁ずる理由にならない。','イを否定した点が誤り。支障のないその他の事業と、役職員への適法な報酬は可能。'],3,'アは○。2012年4月施行の改正後、法定の20分野と不特定多数の利益という要件を照合する。イは○。非営利とは構成員への利益分配を目的としないことで、収入・剰余・給与が全くない意味ではない。ただし役員として報酬を受ける者は役員総数の3分の1以下などの条件がある。ウは×。法定分野の制約はあるが、営利企業との競争を保護するために活動範囲を制限するという根拠ではない。エは×。就業規則等で認める会社員の参加をNPOという形態自体が一律に禁ずることはない。○○××の3。','非営利の公益目的と事業収入・労働報酬の区別',e('npo','csr'),'npo_activity',{'方向':'ア〜エの正誤組合せ。','時点':'平成24年、2012年4月施行の改正後。','限定':'イは法人の目的と利益分配の制限の文脈。無報酬や全ての個人への便益禁止へ拡張しない。'},citations=['cabinet_npo_overview','cabinet_npo_officers'],law=True,figure=True)
add('H25-REG-APT-06','ISO26000の適用対象、持続可能な発展、利害関係者、認証用途を4記述で判定する。',['ア○・イ○・ウ×・エ×','ア○・イ×・ウ×・エ○','ア×・イ×・ウ○・エ○','ア×・イ○・ウ×・エ○','ア×・イ○・ウ×・エ×'],['イ・ウ・エは合うが、アは組織と公人個人を並列の適用対象とする点が誤り。','ア・イ・エの判断が誤り。発展への貢献は目的で、認証用ではない。','ア以外が誤り。株主のみへの限定、外部認証用という位置付けはいずれも違う。','ア・イ・ウは合うが、エの認証用という肯定が誤り。','対象は組織、目的は持続可能な発展への貢献、株主限定でも認証用でもないという判断が全て一致。'],5,'ア×：ISO26000の適用対象は種類・規模を問わない組織であり、公人個人を別の独立した対象として加える説明は適切でない。個人の行為が組織の責任に関係することとは区別する。イ○：持続可能な発展への貢献が包括的目的である。ウ×：組織の決定・活動に利害を持つ従業員、消費者、地域等も関係し、株主だけに限定しない。エ×：要求事項を示す認証用規格ではなく、指針を示す。×○××の5。','社会的責任の対象・利害関係者と認証の区別',e('iso','csr'),'standards_ethics',{'方向':'ア〜エの正誤組合せ。','時点':'2010年発行のISO26000、平成25年度。','対象':'組織の社会的責任。個人の責任一般を否定する設問ではない。'},citations=['iso26000','iso26000_project2010'],figure=True)
add('H26-REG-APT-06','公共の福祉、公衆への説明、公務員の秘密保持、公益通報の対象時点を判定する。',['自由・権利の保持と公共の福祉に適合する私権。','技術の結果へ十分な情報に基づく同意を与える立場にない公衆。','知る権利と技術者による情報開示・説明責任。','公務員の職務上の秘密保持は退職後も続く。','公益通報の保護は犯罪行為が既に起きた場合のみで、起きようとしている場合を含まない。'],['憲法12条と民法1条1項の趣旨を合わせた記述である。権利の無制限な濫用を認めるものではない。','当該技術に対する情報・選択機会・力の非対称性を扱う。全ての市民の一般的能力を低く評価する意味ではない。','判断に必要な情報を説明する責任を述べる。説明すれば必ず同意する、異論を封じてよいとの意味へ拡張しない。','国家公務員法100条は退職後にも適用する。法定の許可等を要する開示の例外があるので、全ての情報を永久に秘匿する意味ではない。','出題当時も、通報対象事実が生じ、又はまさに生じようとしている旨を含む。未来の事実を一律に除く後半が誤り。'],5,'1〜4の対象と限定を確認する。5は、事故や犯罪が実際に起こるまで待つ必要があるとの誤った限定である。平成26年当時の法の定義には、まさに生じようとしている場合が含まれる。現行法で対象者や通報対象事実が拡大したこととは別に、当時からあるこの点を根拠に5を選ぶ。','公益通報の予防的機能と公衆への責任',c('whistleblower','accountability')+e('public'),'whistleblower',{'方向':'最も不適切。','時点':'平成26年当時の公益通報者保護法。','範囲':'通報対象者・目的・対象事実・通報先には別の条件もある。'},discipline='apt_4',citations=['caa_handbook_pre2022','caa_report_current','jp_constitution','jp_civil','jp_national_public'],law=True,verdicts=['適切','適切（技術倫理の文脈）','適切（説明の責任）','適切','不適切'])
add('H27-REG-APT-03','教育の国際認定、技術士補登録、IPEA・APEC称号、二国間の資格審査を判定する。',['JABEEは教育認定を行い、工学・情報・建築の国際的枠組みに対応する。','JABEE認定教育プログラムを修了すれば、第一次試験免除に加えて自動的に技術士補となる。','基準を満たして登録された技術士はIPEA国際エンジニアの称号を用いる。','共通要件による登録でAPECエンジニア・アーキテクトの称号を用いる。','二国間で技術的能力審査の免除を合意でき、日本は豪州2003年・2008年、NZ2009年に関連枠組みを締結した。'],['出題時の教育認定の枠組みを述べる。建築のUNESCO-UIAのシステム認証を、現在のキャンベラ協定加盟へ置換しない。原典の加盟という要約と機関認証の実態は区別する。','文部科学大臣指定課程の修了で技術士補となる資格を得るが、登録を受けて初めて技術士補となる。自動という後半が誤り。','国際登録は基準を満たし審査を受ける別の手続であり、全技術士が自動登録されるとの記述ではない。和文名称は2015年4月にEMFからIPEAへ変更。','能力の同等性を確認する共通称号の制度として適切。称号だけで各国の業務資格が自動的に付与されるわけではない。','文科省は2003年10月の日豪枠組みを、建築技術教育普及センターは2008年日豪・2009年日NZの枠組みを説明する。対象分野や固有事項審査等の条件が残り、全審査の無条件免除ではない。'],2,'教育課程の修了、第一次試験の免除、技術士補となる資格、登録後の名称を順に分ける。技術士法上、試験免除と技術士補登録は同一の行為ではない。2の自動的に技術士補となるという部分を否定する。他肢も、教育の同等性、職業能力の同等性、受入国での業務資格を混同せず読む。','教育認定・国内資格登録・国際称号・業務資格の区別',['theory:engineer_act:international','theory:engineer_act:duties'],'international_registration',{'方向':'最も不適切。','時点':'平成27年。建築はUNESCO-UIA対応の認定、キャンベラ協定は2014年暫定加盟・2019年正式加盟。','対象':'法で指定された認定課程と、別審査の国際登録。'},discipline='apt_0',citations=['engineer_act_current','ipej_associate_registration','jabee_canberra','ipej_ipea2014','mext_international','jaeic_mutual2010'],law=True,verdicts=['適切（出題時の枠組み）','不適切','適切','適切','適切（条件付き）'])
add('H27-REG-APT-15','仕事と生活の調和の効果、継続改善、雇用形態、社会全体の協働を判定する。',['育児・介護・地域での役割を担いながら働け、労働力不足の緩和が期待できる。','企業の社会的責任の実践による信用・人材の確保や定着の改善が期待できる。','多様な価値観・働き方へ、社会環境を継続的に改善する必要がある。','多様な働き方のために、正社員を減らし短期契約の非正規社員を増やす必要がある。','経済界・労働界・国・自治体等が協力する必要がある。'],['働き続けることを妨げる条件を緩和する期待効果である。単一施策で人口問題が必ず解決するという断定ではない。','継続就業の環境は採用・定着にも関係する。全企業で直ちに同じ成果が出るとする保証ではない。','選好やライフステージが異なるため、単一の働き方の押し付けでは満たせない。制度と運用を見直す。','柔軟な時間・場所・休暇・職務設計と、雇用の不安定化は別の軸である。短期非正規への置換は必要条件ではなく、安定した生活を損なうこともある。','職場だけでなく社会基盤や家庭事情にも依存するため、関係主体の役割分担が必要。'],4,'仕事の責任を果たしつつ人生の段階に応じた生活を実現することが目的である。短時間正社員や柔軟な勤務等も選択肢になり、正社員を減らすことへ限定する根拠はない。4が不適切。1・2は期待効果、3・5は改善の進め方として適切である。','多様な選択を支える仕事と生活の調和',e('worklife','organization'),'work_life_balance',{'方向':'最も不適切。','時点':'2007年策定、2010年改定の憲章を背景とする平成27年度。','限定':'効果は期待であり、個別企業への保証ではない。'},citations=['cabinet_worklife'],verdicts=['適切','適切','適切','不適切','適切'])
add('H30-REG-APT-04','倫理規程と情報開示、継続学習、法規制外の危険対応、組織文化、倫理的能力を判定する。',['倫理規程に抵触する可能性があるときは即時・無条件に公開する。','学協会等の組織外の講習にも参加し、能力・資質の向上を図る。','法規制がなくても公衆への危険を察知したら対応する責務がある。','倫理上の問題を自由に議論し行動できる組織文化を育てる。','専門学識に加え倫理的行動のための能力も資質能力に含む。'],['危険の緊急性、事実確認、通報先、必要な範囲、無関係な秘密や個人情報を考慮せず、可能性だけで無条件公開する一般則は不適切。','知識の陳腐化を防ぎ、組織内では得られない専門的な検討にも接する継続学習の趣旨である。','法規制は全危険を事前に網羅しない。専門家として必要な警告や予防措置を検討する。','異論や相談を封じる組織では不正や危険が見落とされやすい。規程と実際の行動環境を結び付ける。','知識を持つだけでは責任ある使用を保証しない。事実と価値の判断、他者への説明・行動の能力が必要。'],1,'倫理規程を守ることと、全ての情報を条件なしに公表することは同一ではない。1の即時・無条件という限定が不適切である。緊急の危害防止を遅らせず、必要な警告と適切な通報を具体的に選ぶ。2〜5は継続学習・公益・対話・倫理能力という責任を支える。','倫理規程を行動へ適用するための条件と能力',e('disclosure','organization','public'),'engineering_ethics',{'方向':'最も不適切。','時点':'平成30年。背景の2011年倫理綱領と現在の2023年指針を区別。'},citations=['ipej_ethics2011','ipej_ethics2023','mext_competency2014'],verdicts=['不適切','適切','適切','適切','適切'])
add('H30-REG-APT-14','5事故の刑事責任を判決と比較する設問と、笹子の不起訴を判決扱いした不適切出題注記を検討する。',['2006年エレベーター事故で、シンドラー社元社員の刑事責任はないとされた。','2005年福知山線事故で、歴代3社長が有罪となった。','2004年回転ドア事故で、メーカー営業開発部長の刑事責任が森ビル関係者より重いとされた。','2000年低脂肪乳食中毒事故で、工場関係者が有罪となった。','2012年笹子トンネル事故で、社長らは予見できないとして刑事責任なしとする判決を受けた。'],['原画像の主語は元社員であり、OCRの社員を補正する。個別被告人の判決と確定段階を示す一次の裁判資料は未確認であり、会社・全保守関係者の責任へ一般化しない。','2017年6月12日最高裁第二小法廷決定、平成27年（あ）741号は、歴代3社長への無罪の第一審を是認した原判断を相当とし、各上告を棄却した。有罪という結末が異なる。','事故防止上の製造者・管理者の役割と、個別被告人への量刑比較は別問題である。刑の重さと理由を一次の判決文で照合できておらず、適切と確定しない。','厚労省資料は停電時の菌増殖・エンテロトキシンA産生と脱脂粉乳の因果を示すが、工場関係者の有罪判決そのものではない。刑事事件の一次記録は追加確認を要する。','原典に付された公式説明は、不起訴処分で刑事裁判に当たらず、試験日現在は検察審査会への審査申立てもあったため不適格とする。不起訴を無罪判決に読み替えられない。'],'ALL','初回独立候補2|5を保持する。2の有罪は、歴代3社長を対象とした最高裁の2017年決定と異なる。5は、公式問題の注記が示すとおり不起訴処分を刑事裁判の判決と同列に置いている。公式正答は不適切出題による全員正解（ALL）であり、初回候補をALLへ上書きしない。1・3・4の個別判決の一次資料は未確認で、全肢を確定済みにしない。全員正解は採点上の措置であり、5事例の記述が全て正しいという意味ではない。','事故の技術的原因と個別の刑事責任・採点措置の区別',['theory:safety:responsibility','theory:safety:cases'],'accident_learning',{'方向':'実際の刑事判決と異なる事例を選ぶ。','原典注記':'選択肢5は不起訴処分で判決ではなく、試験日現在検察審査会への申立てがあり不適切出題。','時点':'平成30年の試験日。後年の経過から逆算しない。','OCR補正':'選択肢1はシンドラー社元社員。'},discipline='apt_3',ambiguity='初回2|5に対し公式ALL。2の誤った有罪は最高裁2017年決定で照合、5の不適格は原典公式注記で確認。1・3・4の個別判決・量刑比較は一次裁判資料未確認。全肢真とせず部分校正、Astra難問査読へ。',citations=['court_jr2017','jtsb_fukuchiyama2007','mhlw_milk2002','mlit_sasago2013'],law=True,verdicts=['判決一次資料要確認','判決と異なる','判決一次資料要確認','判決一次資料要確認','公式注記による不適格'])
add('R01-REG-APT-09','秘密情報のアクセス、相互確認、表示、配置、暗号・閲覧制限、紙削減の6記述で不適切な数を求める。',[str(i)+'項目' for i in range(5)],['単独作業を可能な限り推奨するイが不適切なので0ではない。','イだけが不適切であり1項目となる。','イに加えて他の適切な対策も否定すると数え過ぎとなる。','アクセス権の設定・表示・配置・適切な閲覧制限・紙削減の全てを危険低減策として区別すれば3ではない。','適切な対策まで不適切に数えている。秘密保護と一人作業の推奨を混同しない。'],2,'ア○：情報の分類に応じたアクセス権で、必要のない人の接近を制限する。イ×：相互の確認や責任者のチェックを減らす単独作業の一律推奨は逆方向である。ウ○：秘密の表示で取扱者の認識を支える。エ○：資料・作業が死角になることを減らすが、権限のない者へ画面を見せてよい意味ではない。オ○：暗号と登録ID・端末等の閲覧権制限を適切に設定する対策である。暗号化だけで漏えいが絶対不可能になるという主張ではなく、無断送信を許すものでもない。カ○：電子的アクセス管理と組み合わせ、無権限者が紙に接する機会を減らす。不適切はイの1項目で2。','秘密情報の接近制御と相互確認',['theory:research:secret_management','theory:compliance:secret'],'secret_management',{'方向':'不適切な記述の数。候補0/1/2/3/4。','構成':'ア〜カの6項目。','限定':'オは外部では閲覧できないように設定する対策。暗号自体の万能性や外部送信の許可ではない。'},discipline='apt_1',citations=['meti_secret_handbook2024'])
add('R01-REG-APT-14','ISO26000の社会的責任の原則として、説明責任、透明性、倫理、法の支配、人権を判定する。',['組織は社会・経済・環境への影響に説明責任を負う。','社会・環境に影響する決定と活動を透明にする。','組織は倫理的に行動する。','法の支配を尊重すると同時に自国政府の意向も尊重する。','人権の重要性と普遍性を認識し尊重する。'],['行動の影響に応答し説明する原則に対応する。','判断と活動を説明可能・理解可能にする原則である。無関係な秘密まで無条件に公開する意味ではない。','誠実さ、公平さ等を行動に反映する原則に対応する。','法の支配の尊重を政府の意向への同調へ拡張している。政府も法の制約を受け、意向は法・人権に優先する一般的根拠ではない。','対象国の都合だけで人権の普遍性を否定しない。'],4,'七つの原則は、説明責任、透明性、倫理的行動、利害関係者の利害の尊重、法の支配の尊重、国際行動規範の尊重、人権の尊重である。4の後半はこの原則を政府の意向へ置き換える点が不適切である。七つの中核主題（組織統治、人権、労働慣行等）と原則のリストも別に区別する。','社会的責任における法の支配と政府の意向の区別',e('iso'),'standards_ethics',{'方向':'最も不適切。','時点':'ISO26000:2010、JIS Z26000:2012を背景とする令和元年。'},citations=['iso26000','iso_gri2014'],verdicts=['適切','適切','適切','不適切','適切'])
ud=['公平な利用','利用方法の柔軟性','単純で直観的な使用','必要な情報の認知','エラーの害を抑える設計','少ない身体的努力','接近・使用の寸法と空間']
add('R02-REG-APT-11','年齢・能力・言語等の多様性に配慮するユニバーサルデザインの7原則から、趣旨の違う記述の数を求める。',[str(i)+'項目' for i in range(5)],['列挙された7項目は全て原則の趣旨に対応し、異なるものは0。','一つの原則を除外する根拠がない。','二つの原則を除外する根拠がない。','三つの原則を除外する根拠がない。','四つの原則を除外する根拠がない。'],1,'ア〜キは順に、'+ '、'.join(ud)+'であり、ノースカロライナ州立大学の1997年版の七原則へ全て対応する。したがって異なる趣旨は0項目で1を選ぶ。オのエラーへの寛容はミスを奨励する意味ではなく、偶発的な操作が重大な危害へ直結することを抑える。既存の障壁を除く対策も必要であり、設問前文からバリアフリーが常に過剰投資であるとの一般則を導かない。','利用者の多様性を設計段階から扱う社会的包摂',e('universal'),'universal_design',{'方向':'七原則と趣旨が異なる記述の数。候補0/1/2/3/4。','7記述':dict(zip('アイウエオカキ',ud)),'時点':'原典の国際イベント開催予定は令和2年出題当時の背景。現在の予定へ流用しない。'},citations=['ncsu_ud1997'])
add('R02-REG-APT-15','内部告発の根拠確認、組織手段、同僚の支持、上司への異議、解決策、理解者の6項目で適切な数を求める。',[str(i)+'項目' for i in [6,5,4,3,2]],['6項目とも、慎重に根拠を確かめ是正を進める行動である。','適切な項目を一つ除外している。','適切な項目を二つ除外している。','適切な項目を三つ除外している。','適切な項目を四つ除外している。'],1,'ア○：主張の根拠を自ら検証する。あらゆる努力を違法な証拠収集の許可へ拡張しない。イ○：組織内の通報・相談手段を活用する。ウ○：専門職の支持・検討を求め、独断を点検する。エ○：適当な場合という条件付きで直属上司へ異議を伝える。オ○：事実を指摘するだけでなく具体的な是正案を示す。カ○：上司だけで終わらず他の理解者・相談経路を探す。6項目なので1。これは倫理的な行動の検討で、内部通報が外部通報の法的保護の必須前置手続だという意味ではない。','通報の正当な根拠と是正に向けた手続',c('whistleblower')+e('disclosure'),'whistleblower',{'方向':'適切なものの数。6/5/4/3/2。','構成':'ア〜カの6項目。','限定':'上司への通知は適当な場合。法的保護要件の全体を問う問題ではない。','時点':'令和2年。2022年以降の改正を出題当時の要件として加えない。'},discipline='apt_4',citations=['ipej_ethics2011','caa_handbook_pre2022','caa_current_faq'])
add('R05-REG-APT-02','アクセス権、秘密表示、単独作業、電子的コピー制限、座席配置という漏えい対策を判定する。',['情報分類ごとにアクセス権の設定ルールと適切な範囲を定める。','媒体へ秘密情報であることが分かる表示をする。','複数人を避け、可能な限り単独で秘密情報を扱う。','印刷・複製・外部メディアへのコピー等を制限する設定をする。','作業・資料が死角になりにくい配置を検討する。'],['必要性に基づくアクセス範囲の制御である。権限を無制限に広げる対策ではない。','取扱者が秘密の分類と注意を認識する仕組みを支える。','必要に応じ複数人で相互確認できる体制を整え、単独が必要なら責任者が事前・事後に確認する。単独を最大化する方針は逆である。','持出しの経路を減らす技術的対策となる。印刷禁止やコピーガードが撮影・再入力まで完全に防ぐとの保証ではない。','相互に作業へ注意が向く環境を作る。秘密画面をアクセス権のない人にさらすことを避けるという別条件も守る。'],3,'情報の接近制御、秘密の認識、持出しの困難化、相互チェックを組み合わせる。3だけはチェックを減らす単独作業を一律に推奨しているので不適切。複数人にアクセス権を無制限に与えることとは区別する。','秘密保護におけるアクセス権と相互確認',['theory:research:secret_management','theory:compliance:secret'],'secret_management',{'方向':'最も不適切。','時点':'令和5年。2024年版ハンドブックは現在の背景資料として区別する。','範囲':'5つの対策案。電子的制限の完全防御を主張していない。'},discipline='apt_1',citations=['meti_secret_handbook2024'],verdicts=['適切','適切','不適切','適切','適切'])
add('R05-REG-APT-09','食中毒、回転ドア、鉄道、エレベーター、トンネル天井板の事故原因を比較する。',['2000年食中毒は停電後の不適切な処置と情報開示・回収の遅れ等が関係した。','2004年回転ドアは検知・停止の設計と運用、軽量設計の軽視等に問題があった。','2005年福知山線は曲線での速度超過・ブレーキの遅れと安全確保の組織的問題が関係した。','2006年エレベーター事故はケーブルが破断してかごが落下した。','2012年笹子は天井板の接着系アンカー等の脱落、設計・施工・維持管理が関係した。'],['厚労省は停電時の菌増殖・毒素産生を説明し、当事企業も汚染原料と対応の問題を振り返る。個別の経営者の刑事責任を認定する記述ではない。','検知・非常停止だけに安全を委ね、重量・慣性と使用条件を軽視すると停止前の挟まれ危険が残る。大学の技術者倫理事例集は軽量設計からの変更を扱う。事故の一般的教訓と個別被告人の判決を分ける。','事故調査報告の直接原因は制限速度を大幅に超えた進入で、運転士管理方法の関与は可能性として記す。原典のATS未設置は当該曲線の速度超過防止機能を指し、列車の全ATS不搭載を意味しない。','公式の事故調査は、戸が開いた状態でかごが上昇し利用者が挟まれた事象を扱う。ケーブル破断による落下とした故障機構・運動方向が事実と異なる。','国交省委員会は接着系アンカーの引抜き等と、設計・施工・点検の課題を整理する。単純な材料の経年劣化だけに原因を限定しない。'],4,'4は事故の機構を逆にしている。2006年の事象は、かごが戸開状態で不意に上昇した際の挟まれであり、ケーブル破断・落下ではない。1〜3・5は、直接の物理的事象だけでなく、その前提を維持できなかった設計・運用・組織上の条件も述べる。鉄道のATSの機能と、組織背景の推定の強さを区別して4を選ぶ。','事故機構の再現と設計・運用・組織の因果の区別',['theory:safety:cases','theory:safety:barriers'],'accident_learning',{'方向':'事実と異なるもの。','事故年':'2000、2004、2005、2006、2012。','条件':'鉄道のATSは当該急曲線の速度超過防止。エレベーターの運動方向を実画像と政府事故調査で確認。'},discipline='apt_3',citations=['mhlw_milk2002','milk_incident_company','muroran_ethics_cases','jtsb_fukuchiyama2007','caa_elevator2006','mlit_sasago2013'],verdicts=['適切（事故対応の説明）','適切（安全の教訓）','適切（機能・推定の限定に注意）','事実と異なる','適切（複合的要因）'])
